using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){var rows=new List<string>();foreach(var p in Directory.GetFiles("Assets/Optimization/GeneratedMeshes","*.asset")){var m=AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>(p);if(m)rows.Add("MESH "+p+" vertices="+m.vertexCount+" tris="+Enumerable.Range(0,m.subMeshCount).Sum(i=>(long)m.GetIndexCount(i)/3));}foreach(var p in Directory.GetFiles("Assets/World","*Terrain.asset",SearchOption.AllDirectories)){var t=AssetDatabase.LoadAssetAtPath<TerrainData>(p);if(!t)continue;rows.Add("TERRAIN "+p+" instances="+t.treeInstanceCount);for(int i=0;i<t.treePrototypes.Length;i++)rows.Add("TREE "+i+" count="+t.treeInstances.Count(q=>q.prototypeIndex==i)+" path="+AssetDatabase.GetAssetPath(t.treePrototypes[i].prefab));}File.WriteAllLines("Validation/FinalWorld/asset_stats.txt",rows);result.Log("Saved asset stats");}}

